function d(e){if(e==null||e==="")return"";const t=e instanceof Date?e:new Date(e);if(Number.isNaN(t.getTime()))return"";const o=String(t.getDate()).padStart(2,"0"),r=String(t.getMonth()+1).padStart(2,"0"),n=t.getFullYear();return`${o}/${r}/${n}`}function y(e){if(!e)return"";const t=String(e).trim(),o=/^(\d{2})\/(\d{2})\/(\d{4})$/.exec(t);if(!o)return"";const[,r,n,s]=o,i=Number(r),a=Number(n),c=Number(s);if(a<1||a>12||i<1||i>31||c<1900||c>2100)return"";const m=new Date(`${s}-${n}-${r}T00:00:00`);return m.getFullYear()!==c||m.getMonth()+1!==a||m.getDate()!==i?"":`${s}-${n}-${r}`}function u(e){const t=String(e||"").replace(/\D/g,"").slice(0,8);return t.length<=2?t:t.length<=4?`${t.slice(0,2)}/${t.slice(2)}`:`${t.slice(0,2)}/${t.slice(2,4)}/${t.slice(4)}`}export{u as a,y as d,d as f};
